/**
 * Static-build API: answers the same `/api/*` paths the FastAPI backend serves, entirely in the browser.
 *   content   -> JSON files under /static-data (generated by scripts/export_static.py)
 *   SQL lab   -> DuckDB-WASM        (sqlEngine.ts)
 *   Python    -> Pyodide worker     (pythonEngine.ts)
 *   state     -> this visitor's localStorage (nothing is shared between visitors)
 */
import { expectedSql, resetSql, runSql, sqlSchema, validateSql } from './sqlEngine'
import { runPython, validatePython } from './pythonEngine'

const STATE_KEY = 'delab.state'
const BACKUP_KEY = 'delab.backups'
const MAX_BACKUPS = 5

const url = (name: string) => `${import.meta.env.BASE_URL}static-data/${name}`
const files = new Map<string, Promise<unknown>>()
function json<T>(name: string): Promise<T> {
  if (!files.has(name)) {
    files.set(name, fetch(url(name)).then((r) => { if (!r.ok) throw new Error(`Request failed (${r.status})`); return r.json() }).catch((e) => { files.delete(name); throw e }))
  }
  return files.get(name) as Promise<T>
}

interface SqlSolution { solution: string; explain: string; ordered: boolean; setup: string | null }
interface PySolution { solution: string; explain: string; tests: string }
interface Backup { name: string; size: number; modified: number; data: string }

const readBackups = (): Backup[] => { try { return JSON.parse(localStorage.getItem(BACKUP_KEY) ?? '[]') as Backup[] } catch { return [] } }
const readState = (): unknown => { try { return JSON.parse(localStorage.getItem(STATE_KEY) ?? 'null') } catch { return null } }
const notFound = () => new Error('Request failed (404)')

export async function staticRequest(method: string, path: string, body?: unknown): Promise<unknown> {
  const b = (body ?? {}) as Record<string, unknown>
  let m: RegExpMatchArray | null

  if (method === 'GET') {
    if (path === '/api/content/modules') return json('modules.json')
    if (path === '/api/content/lessons') return json('lessons-index.json')
    if ((m = path.match(/^\/api\/content\/lessons\/([A-Za-z0-9_.-]+)$/))) return json(`lessons/${decodeURIComponent(m[1])}.json`)
    if (path === '/api/content/projects') return json('projects.json')
    if (path === '/api/content/scenarios') return json('scenarios.json')
    if (path === '/api/content/mcq') return json('mcq.json')
    if (path === '/api/content/questions') return json('questions.json')
    if (path === '/api/sql/exercises') return json('sql-exercises.json')
    if (path === '/api/python/exercises') return json('py-exercises.json')
    if (path === '/api/sql/schema') return sqlSchema()
    if ((m = path.match(/^\/api\/sql\/exercises\/([\w.-]+)\/(expected|solution)$/))) {
      const sol = (await json<Record<string, SqlSolution>>('sql-solutions.json'))[m[1]]
      if (!sol) throw notFound()
      return m[2] === 'solution' ? { solution: sol.solution, explain: sol.explain } : expectedSql(sol.solution, sol.setup)
    }
    if ((m = path.match(/^\/api\/python\/exercises\/([\w.-]+)\/solution$/))) {
      const sol = (await json<Record<string, PySolution>>('py-solutions.json'))[m[1]]
      if (!sol) throw notFound()
      return { solution: sol.solution, explain: sol.explain }
    }
    if (path === '/api/state') { const app = readState(); return app ? { app } : {} }
    if (path === '/api/backup') return readBackups().map(({ name, size, modified }) => ({ name, size, modified })).reverse()
    if (path === '/api/ai/status') return { configured: false }
  }

  if (method === 'POST') {
    if (path === '/api/sql/run') return runSql(String(b.sql ?? ''))
    if (path === '/api/sql/reset') return resetSql()
    if (path === '/api/sql/validate') {
      const sol = (await json<Record<string, SqlSolution>>('sql-solutions.json'))[String(b.exercise_id)]
      if (!sol) throw notFound()
      return validateSql(String(b.sql ?? ''), sol.solution, sol.ordered, sol.setup)
    }
    if (path === '/api/python/run') return runPython(String(b.code ?? ''))
    if (path === '/api/python/validate') {
      const sol = (await json<Record<string, PySolution>>('py-solutions.json'))[String(b.exercise_id)]
      if (!sol) throw notFound()
      return validatePython(String(b.code ?? ''), sol.tests)
    }
    if (path === '/api/backup') {
      const data = localStorage.getItem(STATE_KEY) ?? '{}'
      const now = new Date()
      const p = (n: number) => String(n).padStart(2, '0')
      const name = `backup-${now.getFullYear()}${p(now.getMonth() + 1)}${p(now.getDate())}-${p(now.getHours())}${p(now.getMinutes())}${p(now.getSeconds())}.json`
      const list = [...readBackups(), { name, size: data.length, modified: now.getTime() / 1000, data }].slice(-MAX_BACKUPS)
      try { localStorage.setItem(BACKUP_KEY, JSON.stringify(list)) } catch { throw new Error('Browser storage is full. Export your progress to a file instead.') }
      return { ok: true, name }
    }
    if (path === '/api/backup/restore') {
      const found = readBackups().find((x) => x.name === b.name)
      if (!found) throw notFound()
      localStorage.setItem(STATE_KEY, found.data)
      return { ok: true }
    }
  }

  if (method === 'PUT' && path === '/api/state/app') {
    localStorage.setItem(STATE_KEY, JSON.stringify(b.value))
    return { ok: true }
  }

  if (method === 'DELETE' && path === '/api/state') {
    localStorage.removeItem(STATE_KEY)
    return { ok: true }
  }

  throw notFound()
}
